import{_ as a,c as o,o as t,ag as c}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"解释原理说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/explanation-principle-description.md","filePath":"zh_CN/explanation-principle-description.md","lastUpdated":1769658044000}'),r={name:"zh_CN/explanation-principle-description.md"};function n(l,e,i,d,s,p){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="解释原理说明" tabindex="-1">解释原理说明 <a class="header-anchor" href="#解释原理说明" aria-label="Permalink to &quot;解释原理说明&quot;">​</a></h1><p><a href="./">返回目录</a></p><p><strong>深度开发</strong>中通过make工具链将脚本文件解释到<code>./ezgal/csharp/FlowData.cs</code>文件，<strong>低代码开发</strong>则依赖<code>./ezgal/csharp/Global.cs</code>文件对<code>./ezgal/script</code>文件夹内的脚本演出脚本即时读取。剧本演出脚本解析为json格式后在<code>./ezgal/scene/game.tscn</code>进行统一调用。</p><h2 id="解析到json" tabindex="-1">解析到json <a class="header-anchor" href="#解析到json" aria-label="Permalink to &quot;解析到json&quot;">​</a></h2><p>解析过程<code>./ezgal/csharp/Global.cs</code>与make工具链的实现为同源的，核心解析工具均为<code>read_file()</code>函数，核心实现功能如下：</p><h3 id="文件逐行处理" tabindex="-1">文件逐行处理 <a class="header-anchor" href="#文件逐行处理" aria-label="Permalink to &quot;文件逐行处理&quot;">​</a></h3><p>通过读取文件，对文件进行逐行读取，各行<code>string line</code>限制不为null，删除字符串的头尾空白符</p><h3 id="大括号处理" tabindex="-1">大括号处理 <a class="header-anchor" href="#大括号处理" aria-label="Permalink to &quot;大括号处理&quot;">​</a></h3><p>当存在左括号<code>{</code>存在时当前行<code>string line</code>将持续添加下一行信息直到右括号闭合<code>}</code>，大括号内信息使用<code>set_braces_func1()</code>函数统一处理</p><h3 id="选项处理" tabindex="-1">选项处理 <a class="header-anchor" href="#选项处理" aria-label="Permalink to &quot;选项处理&quot;">​</a></h3><p>当读取<code>[选项]</code>时存储<code>flow_line.type=&quot;选项&quot;</code>，跳转为其他类型前将每行<code>line</code>作为一个选项存储于<code>set_option</code></p><h2 id="json处理逻辑" tabindex="-1">json处理逻辑 <a class="header-anchor" href="#json处理逻辑" aria-label="Permalink to &quot;json处理逻辑&quot;">​</a></h2><h3 id="文字处理" tabindex="-1">文字处理 <a class="header-anchor" href="#文字处理" aria-label="Permalink to &quot;文字处理&quot;">​</a></h3><p>文字处理工作需要提前设置<code>type=&quot;对话框&quot;</code>或<code>type=&quot;全屏&quot;</code>，对话将根据type类型将文字显示在对应窗口中。后续type为空时将自动沿用上一次存储的type类型。</p><ul><li>图片功能集合：可以在文字处理中同时加入图片功能，图片将在文字处理的当前行更新。</li><li>声音功能集合：可以在文字处理中同时加入声音功能，声音将在文字处理的当前行更新。</li><li>跳转功能集合：可以在文字处理中同时加入跳转功能，跳转会在文字处理完的下一行跳转到新的场景。</li></ul><h3 id="独立演出处理" tabindex="-1">独立演出处理 <a class="header-anchor" href="#独立演出处理" aria-label="Permalink to &quot;独立演出处理&quot;">​</a></h3><p>当演出需要作为单独进行时需要单独设置<code>type=&quot;演出&quot;</code>，运行到当前行的时候不包含文字处理流程.</p><h3 id="空段落处理" tabindex="-1">空段落处理 <a class="header-anchor" href="#空段落处理" aria-label="Permalink to &quot;空段落处理&quot;">​</a></h3><blockquote><p>目前这是个不完美的解决方案，未来这是Ezlang重点需要解决的问题。</p></blockquote><p>针对不规范的代码编写方式有可能存在空段落的情况，空段落在处理过程中直接跳过到下一个段落。</p>',20)])])}const _=a(r,[["render",n]]);export{u as __pageData,_ as default};
